#include "fsharp_table.h"
#include <algorithm>
#include <cstdint>
#include <functional>
#include <limits>
#include <map>
#include <set>
#include <string_view>
#include <utility>

namespace reflgen::generator
{
    namespace
    {
        constexpr std::string_view banner =
            "// <auto-generated/> Generated by reflgen. Do not edit; edit the native ABI header instead.\n";

        bool identifier(std::string_view name)
        {
            const auto letter = [](char c) {
                return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || c == '_';
            };
            return !name.empty() && letter(name.front()) &&
                   std::all_of(name.begin(), name.end(), [&](char c) { return letter(c) || (c >= '0' && c <= '9'); });
        }

        bool qualified(std::string_view name, std::string_view separator)
        {
            while (true)
            {
                const auto next = name.find(separator);
                if (!identifier(name.substr(0, next))) return false;
                if (next == std::string_view::npos) return true;
                name.remove_prefix(next + separator.size());
            }
        }

        std::string flatten(std::string name)
        {
            std::size_t start = 0;
            while ((start = name.find("::", start)) != std::string::npos) name.replace(start, 2, "_");
            return name;
        }

        std::string fs_name(const std::string& name) { return "``" + name + "``"; }

        std::string quote(std::string_view value)
        {
            constexpr char hex[] = "0123456789abcdef";
            std::string result = "\"";
            for (const unsigned char c : value)
            {
                if (c == '\\' || c == '"') { result += '\\'; result += static_cast<char>(c); }
                else if (c < 32 || c == 127)
                {
                    result += "\\u00";
                    result += hex[c >> 4U];
                    result += hex[c & 15U];
                }
                else result += static_cast<char>(c);
            }
            return result + '"';
        }

        bool includable(std::string_view path)
        {
            return !path.empty() && path.find_first_of("\"\\\r\n") == std::string_view::npos &&
                   std::none_of(path.begin(), path.end(), [](unsigned char c) { return c < 32 || c == 127; });
        }

        template<class Range, class Emit> std::string json_array(const Range& range, Emit emit)
        {
            std::string result = "[";
            bool first = true;
            for (const auto& item : range)
            {
                if (!first) result += ',';
                first = false;
                result += emit(item);
            }
            return result + ']';
        }

        std::string type_json(const declaration_type& type)
        {
            return "{\"kind\":" + quote(type.kind) + ",\"canonical\":" + quote(type.canonical_spelling) +
                ",\"declaration\":" + quote(type.declaration) + ",\"size\":" + std::to_string(type.size_bytes) +
                ",\"alignment\":" + std::to_string(type.align_bytes) +
                ",\"const\":" + (type.is_const ? "true" : "false") +
                ",\"volatile\":" + (type.is_volatile ? "true" : "false") +
                ",\"pointee\":" + (type.pointee ? type_json(*type.pointee) : "null") +
                ",\"element\":" + (type.element_type ? type_json(*type.element_type) : "null") +
                ",\"length\":" + std::to_string(type.array_size) +
                ",\"underlying\":" + (type.enum_underlying ? type_json(*type.enum_underlying) : "null") +
                ",\"result\":" + (type.function_result ? type_json(*type.function_result) : "null") +
                ",\"parameters\":" + json_array(type.function_parameters, type_json) +
                ",\"calling_convention\":" + quote(type.function_calling_convention) +
                ",\"exception_specification\":" + quote(type.function_exception_specification) +
                ",\"variadic\":" + (type.function_variadic ? "true" : "false") +
                ",\"prototype\":" + (type.function_has_prototype ? "true" : "false") + '}';
        }

        std::string value_json(const value_model& value)
        {
            return "{\"name\":" + quote(flatten(value.target.declaration)) + ",\"native_type\":" +
                quote(value.target.declaration) + ",\"kind\":" + quote(value.target.kind) +
                ",\"size\":" + std::to_string(value.target.size_bytes) + ",\"alignment\":" +
                std::to_string(value.align_bytes) + ",\"fields\":" + json_array(value.fields, [](const auto& f) {
                    return "{\"name\":" + quote(f.name) + ",\"offset\":" + std::to_string(f.offset_bytes) +
                           ",\"type\":" + type_json(f.type) + '}';
                }) + ",\"underlying\":" + type_json(value.underlying) +
                ",\"cases\":" + json_array(value.cases, [](const auto& c) {
                    return "{\"name\":" + quote(c.name) + ",\"value\":" + quote(c.value) + '}';
                }) + '}';
        }

        std::string hash_contract(std::string_view contract)
        {
            std::uint64_t hash = 14695981039346656037ULL;
            for (const unsigned char c : contract) { hash ^= c; hash *= 1099511628211ULL; }
            constexpr char digits[] = "0123456789abcdef";
            std::string text(16, '0');
            for (std::size_t i = text.size(); i > 0; --i) { text[i - 1] = digits[hash & 15U]; hash >>= 4U; }
            return text;
        }

        struct lowered_type
        {
            std::string name;
            long long size = -1;
            long long alignment = -1;
        };

        struct array_layout
        {
            std::string name;
            lowered_type element;
            long long count;
            long long size;
            long long alignment;
        };

        struct value_layout
        {
            const value_model* model;
            std::string name;
            std::vector<lowered_type> fields;
        };

        struct function_layout
        {
            const value_field_model* field;
            std::string delegate_name;
            std::string calling_convention;
            lowered_type result;
            std::vector<lowered_type> parameters;
        };

        struct table_layout
        {
            const native_table_model* model;
            long long version_offset = -1;
            long long size_offset = -1;
            std::vector<function_layout> functions;
        };

        class emitter
        {
          public:
            emitter(const target_model& target, const fsharp_table_options& options, diagnostics& report)
                : target_(target), options_(options), report_(report)
            {
                windows_ = target.triple.find("windows") != std::string::npos || target.triple.find("mingw") != std::string::npos;
                linux_ = target.triple.find("linux") != std::string::npos;
                architecture_ = target.triple.substr(0, target.triple.find('-'));
            }

            fsharp_table_output run(const std::vector<native_table_model>& input)
            {
                if (!identifier(options_.module_name) || !qualified(options_.managed_namespace, "."))
                    error("RG0400", {}, "F# table module and namespace must contain ASCII identifiers");
                if (!input.empty() && (!supported_target() || target_.triple.empty()))
                    error("RG0402", input.front().position,
                          "native tables currently support x64 Windows and Linux with 64-bit pointers");
                std::vector<const native_table_model*> ordered;
                for (const auto& table : input) ordered.push_back(&table);
                std::sort(ordered.begin(), ordered.end(), [](const auto* a, const auto* b) { return a->managed_name < b->managed_name; });
                for (const auto* table : ordered)
                {
                    for (const auto& value : table->values)
                    {
                        const auto [old, inserted] = models_.emplace(value.target.declaration, &value);
                        if (!inserted && value_json(*old->second) != value_json(value))
                            error("RG0401", value.position, "conflicting native layouts for '" + value.target.declaration + "'");
                    }
                }
                // Reserve public helper/member names as well as CLR type names. No flattened collision is hidden.
                for (const auto& name : {"RootedCallback", "AbiFingerprint", "validateLayouts", "validateTarget"}) names_.insert(name);
                for (const auto* table : ordered)
                {
                    reserve(table->managed_name, table->position);
                    reserve(table->managed_name + "Version", table->position);
                    reserve(table->managed_name + "Size", table->position);
                    lower_table(*table);
                }
                // A pointer edge never creates an F# value dependency. Defer its optional POD declaration
                // until all by-value dependencies are ordered (A contains B*, while B contains A is valid).
                while (!pointed_values_.empty())
                {
                    const std::string name = *pointed_values_.begin();
                    pointed_values_.erase(pointed_values_.begin());
                    lower_value(name, models_.at(name)->position);
                }
                if (report_.has_errors()) return {};
                fsharp_table_output output;
                const auto tables_json = json_array(layouts_, [](const auto& layout) {
                    const auto& t = *layout.model;
                    return "{\"name\":" + quote(t.managed_name) + ",\"native_type\":" + quote(t.table.target.declaration) +
                        ",\"version\":" + std::to_string(t.version) + ",\"version_expression\":" + quote(t.version_expression) +
                        ",\"size\":" + std::to_string(t.table.target.size_bytes) + ",\"alignment\":" +
                        std::to_string(t.table.align_bytes) + ",\"version_field\":" + quote(t.version_field) +
                        ",\"size_field\":" + quote(t.size_field) + ",\"fields\":" + json_array(t.table.fields, [](const auto& f) {
                            return "{\"name\":" + quote(f.name) + ",\"offset\":" + std::to_string(f.offset_bytes) +
                                   ",\"type\":" + type_json(f.type) + '}';
                        }) + '}';
                });
                std::vector<const value_model*> manifest_values;
                for (const auto& [name, value] : completed_) { (void)name; manifest_values.push_back(value); }
                const auto values_json = json_array(manifest_values, [](const auto* v) { return value_json(*v); });
                const std::string contract = "{\"format\":\"reflgen.fsharp-native\",\"version\":1,\"module\":" +
                    quote(options_.module_name) + ",\"namespace\":" + quote(options_.managed_namespace) +
                    ",\"target\":" + quote(target_.triple) + ",\"pointer_width\":" + std::to_string(target_.pointer_width) +
                    ",\"tables\":" + tables_json + ",\"values\":" + values_json + '}';
                output.fingerprint = hash_contract(contract);
                output.manifest_json = contract.substr(0, contract.size() - 1) + ",\"fingerprint\":" + quote(output.fingerprint) + "}\n";
                output.cpp_source = native_source(output.fingerprint);
                output.fsharp_source = managed_source(output.fingerprint);
                return output;
            }

          private:
            void error(std::string_view code, const source_position& position, const std::string& message)
            {
                report_.error(code, position, message);
            }

            void reserve(const std::string& name, const source_position& position)
            {
                if (!identifier(name)) error("RG0400", position, "generated F# name must be an ASCII identifier: '" + name + "'");
                else if (!names_.insert(name).second) error("RG0403", position, "generated native-table name collision: '" + name + "'");
            }

            bool supported_target() const
            {
                const bool x64 = architecture_ == "x86_64" || architecture_ == "amd64";
                return (windows_ || linux_) && x64 && target_.pointer_width == 64;
            }

            std::string callconv(const declaration_type& function, const source_position& position)
            {
                const auto& convention = function.function_calling_convention;
                if (convention == "c" || convention == "default") return "Cdecl";
                if (convention == "x86_stdcall" && windows_) return "StdCall";
                if (convention == "win64" && windows_ && target_.pointer_width == 64) return "StdCall";
                if (convention == "x86_64_sysv" && linux_ && architecture_ == "x86_64") return "Cdecl";
                error("RG0402", position, "unsupported native function calling convention: '" + convention + "'");
                return {};
            }

            lowered_type lower(const declaration_type& type, const std::string& context,
                               const source_position& position, bool allow_void = false)
            {
                const auto reject = [&]() -> lowered_type {
                    error("RG0402", position, "unsupported native table type '" + type.canonical_spelling + "' in " + context);
                    return {};
                };
                if (type.is_volatile) return reject();
                if (type.kind == "void" && allow_void) return {"unit", 0, 1};
                if (type.kind == "pointer" && type.pointee && type.size_bytes == target_.pointer_width / 8)
                {
                    if (type.pointee->kind == "function")
                    {
                        const auto& function = *type.pointee;
                        if (!function.function_has_prototype || function.function_variadic || !function.function_result ||
                            (function.function_exception_specification != "none" && function.function_exception_specification != "noexcept"))
                            return reject();
                        (void)callconv(function, position);
                    }
                    // Pointed-to objects are borrowed. Complete representable PODs are also declared for buffers;
                    // incomplete/non-POD C++ objects remain opaque without weakening by-value validation.
                    if ((type.pointee->kind == "record" || type.pointee->kind == "enum") &&
                        representable(type.pointee->declaration, {}))
                        if (!completed_.contains(type.pointee->declaration) && !visiting_.contains(type.pointee->declaration))
                            pointed_values_.insert(type.pointee->declaration);
                    return {"nativeint", type.size_bytes, type.align_bytes};
                }
                if (type.kind == "record" || type.kind == "enum")
                {
                    if (!representable(type.declaration, {})) return reject();
                    lower_value(type.declaration, position);
                    return {fs_name(flatten(type.declaration)), type.size_bytes, type.align_bytes};
                }
                if (type.kind == "array")
                {
                    if (!type.element_type || type.array_size <= 0 || type.array_size > 16384 ||
                        type.element_type->size_bytes <= 0 || type.array_size > 2147483647LL / type.element_type->size_bytes ||
                        type.size_bytes != type.array_size * type.element_type->size_bytes) return reject();
                    const std::string name = context + "_Array";
                    reserve(name, position);
                    const auto element = lower(*type.element_type, name + "_Element", position);
                    arrays_.push_back({name, element, type.array_size, type.size_bytes, type.align_bytes});
                    ordered_definitions_.push_back({true, arrays_.size() - 1});
                    return {fs_name(name), type.size_bytes, type.align_bytes};
                }
                const bool signed_integer = type.kind == "signed_integer";
                const bool unsigned_integer = type.kind == "unsigned_integer";
                if (signed_integer || unsigned_integer ||
                    (type.kind == "character" && (type.canonical_spelling == "char16_t" || type.canonical_spelling == "char32_t")))
                {
                    if (type.size_bytes != 1 && type.size_bytes != 2 && type.size_bytes != 4 && type.size_bytes != 8) return reject();
                    return {(signed_integer ? "int" : "uint") + std::to_string(type.size_bytes * 8), type.size_bytes, type.align_bytes};
                }
                if (type.kind == "floating_point")
                {
                    if (type.canonical_spelling == "float" && type.size_bytes == 4) return {"float32", 4, type.align_bytes};
                    if (type.canonical_spelling == "double" && type.size_bytes == 8) return {"float", 8, type.align_bytes};
                }
                // Native bool is deliberately not inferred as a CLR bool (which has different default marshalling).
                return reject();
            }

            bool simple_shape(const declaration_type& type, std::set<std::string> seen) const
            {
                if (type.is_volatile || type.size_bytes <= 0 || type.align_bytes <= 0 || type.align_bytes > 8) return false;
                if (type.kind == "pointer") return type.pointee && type.size_bytes == target_.pointer_width / 8;
                if (type.kind == "record" || type.kind == "enum") return representable(type.declaration, std::move(seen));
                if (type.kind == "array") return type.array_size > 0 && type.array_size <= 16384 && type.element_type &&
                    simple_shape(*type.element_type, std::move(seen));
                if (type.kind == "signed_integer" || type.kind == "unsigned_integer")
                    return type.size_bytes == 1 || type.size_bytes == 2 || type.size_bytes == 4 || type.size_bytes == 8;
                if (type.kind == "character") return type.canonical_spelling == "char16_t" || type.canonical_spelling == "char32_t";
                return type.kind == "floating_point" &&
                    ((type.canonical_spelling == "float" && type.size_bytes == 4) || (type.canonical_spelling == "double" && type.size_bytes == 8));
            }

            bool representable(const std::string& name, std::set<std::string> seen) const
            {
                const auto it = models_.find(name);
                if (it == models_.end() || !seen.insert(name).second || seen.size() > 64 || !qualified(name, "::")) return false;
                const auto& value = *it->second;
                if (value.target.size_bytes <= 0 || value.target.size_bytes > 2147483647LL || value.align_bytes <= 0 ||
                    value.align_bytes > 8 || value.is_union || value.has_bases || value.has_virtual_members || value.has_nontrivial_destructor)
                    return false;
                if (value.target.kind == "enum") return simple_shape(value.underlying, std::move(seen));
                if (value.fields.empty()) return false;
                long long alignment = 1;
                long long end = 0;
                for (const auto& field : value.fields)
                {
                    if (!field.is_public || field.is_bitfield || !identifier(field.name) || field.offset_bytes < end ||
                        !simple_shape(field.type, seen) || field.offset_bytes % field.type.align_bytes != 0 ||
                        field.offset_bytes > value.target.size_bytes - field.type.size_bytes) return false;
                    alignment = (std::max)(alignment, field.type.align_bytes);
                    end = field.offset_bytes + field.type.size_bytes;
                }
                // CLR explicit layouts cannot express an independently over-aligned or packed native value ABI.
                return alignment == value.align_bytes && value.target.size_bytes % alignment == 0;
            }

            void lower_value(const std::string& name, const source_position& position)
            {
                if (completed_.contains(name) || visiting_.contains(name)) return;
                const auto* value = models_.at(name);
                if (!qualified(name, "::")) { error("RG0401", position, "native value requires a named non-template declaration"); return; }
                visiting_.insert(name);
                value_layout layout{value, flatten(name), {}};
                reserve(layout.name, value->position);
                if (value->target.kind == "enum")
                {
                    layout.fields.push_back(lower(value->underlying, layout.name, value->position));
                    std::set<std::string> cases;
                    for (const auto& item : value->cases)
                        if (!identifier(item.name) || !cases.insert(item.name).second)
                            error("RG0401", value->position, "enum case names must be unique ASCII identifiers");
                }
                else
                    for (const auto& field : value->fields)
                        layout.fields.push_back(lower(field.type, layout.name + "_" + field.name, value->position));
                values_.push_back(std::move(layout));
                ordered_definitions_.push_back({false, values_.size() - 1});
                visiting_.erase(name);
                completed_.emplace(name, value);
            }

            void lower_table(const native_table_model& table)
            {
                const auto& native = table.table;
                if (!qualified(table.alias, "::") || !qualified(native.target.declaration, "::") ||
                    !identifier(table.version_field) || !identifier(table.size_field) || table.version_field == table.size_field ||
                    table.version < 0 || table.version > 2147483647LL ||
                    !qualified(table.version_expression.starts_with("::") ? std::string_view(table.version_expression).substr(2) :
                               std::string_view(table.version_expression), "::") ||
                    !includable(table.position.file) || native.target.kind != "record" || native.target.is_const ||
                    native.target.is_volatile || native.target.size_bytes < 8 || native.target.size_bytes > 2147483647LL ||
                    native.align_bytes != target_.pointer_width / 8 || native.has_bases || native.is_union ||
                    native.has_virtual_members || native.has_nontrivial_destructor)
                {
                    error("RG0401", table.position, "native table requires a named naturally aligned record, two int32 header fields and a compiler-evaluated version");
                    return;
                }
                table_layout layout{&table, -1, -1, {}};
                long long end = 0;
                std::set<std::string> fields;
                for (const auto& field : native.fields)
                {
                    if (!field.is_public || field.is_bitfield || !identifier(field.name) || !fields.insert(field.name).second ||
                        field.offset_bytes < end || field.type.size_bytes <= 0 || field.offset_bytes > native.target.size_bytes - field.type.size_bytes)
                    {
                        error("RG0401", table.position, "native table fields must be public, nonoverlapping, named fields with known offsets");
                        continue;
                    }
                    end = field.offset_bytes + field.type.size_bytes;
                    if (field.name == table.version_field || field.name == table.size_field)
                    {
                        if (field.type.kind != "signed_integer" || field.type.size_bytes != 4 || field.type.is_const ||
                            field.type.is_volatile || field.offset_bytes % 4 != 0 || field.offset_bytes > 4)
                            error("RG0401", table.position, "version and size must be the first two int32 fields of the native table");
                        if (field.name == table.version_field) layout.version_offset = field.offset_bytes;
                        else layout.size_offset = field.offset_bytes;
                        continue;
                    }
                    if (field.type.kind != "pointer" || field.type.is_const || field.type.is_volatile || !field.type.pointee ||
                        field.type.pointee->kind != "function" || field.type.size_bytes != target_.pointer_width / 8 ||
                        field.offset_bytes % (target_.pointer_width / 8) != 0 || field.offset_bytes < 8)
                    {
                        error("RG0401", table.position, "native table payload fields must be naturally aligned function pointers");
                        continue;
                    }
                    const auto& function = *field.type.pointee;
                    if (!function.function_has_prototype || function.function_variadic || !function.function_result ||
                        (function.function_exception_specification != "none" && function.function_exception_specification != "noexcept"))
                    {
                        error("RG0402", table.position, "native table functions require complete nonvariadic prototypes and known exception specifications");
                        continue;
                    }
                    function_layout method{&field, table.managed_name + "_" + field.name + "_Delegate",
                                           callconv(function, table.position), {}, {}};
                    reserve(method.delegate_name, table.position);
                    reserve("root_" + table.managed_name + "_" + field.name + "_callback", table.position);
                    method.result = lower(*function.function_result, method.delegate_name + "_Result", table.position, true);
                    for (std::size_t i = 0; i < function.function_parameters.size(); ++i)
                    {
                        const auto& parameter = function.function_parameters[i];
                        if (parameter.kind == "array")
                            error("RG0402", table.position, "function parameters must use pointers rather than array values");
                        method.parameters.push_back(lower(parameter, method.delegate_name + "_Argument" + std::to_string(i), table.position));
                    }
                    if (field.name == "Bind" || field.name == "Address" || field.name == "AvailableBytes")
                        error("RG0403", table.position, "native table field conflicts with a generated binding member: '" + field.name + "'");
                    layout.functions.push_back(std::move(method));
                }
                if (layout.version_offset < 0 || layout.size_offset < 0 || layout.version_offset == layout.size_offset || layout.functions.empty())
                    error("RG0401", table.position, "native table must contain both header fields and at least one function pointer");
                layouts_.push_back(std::move(layout));
            }

            std::string cpp_type(const declaration_type& type) const
            {
                if (type.kind == "pointer" && type.pointee && type.pointee->kind == "function")
                {
                    const auto& f = *type.pointee;
                    const bool stdcall = f.function_calling_convention == "x86_stdcall" || f.function_calling_convention == "win64";
                    std::string result = cpp_type(*f.function_result) + " (REFLGEN_NATIVE_" + (stdcall ? "STDCALL" : "CDECL") + "*)(";
                    for (std::size_t i = 0; i < f.function_parameters.size(); ++i)
                    {
                        if (i) result += ", ";
                        result += cpp_type(f.function_parameters[i]);
                    }
                    return result + ')' + (f.function_exception_specification == "noexcept" ? " noexcept" : "");
                }
                return type.canonical_spelling;
            }

            std::string native_source(const std::string& fingerprint) const
            {
                std::string cpp(banner);
                cpp += "#include <cstddef>\n#include <cstdint>\n#include <climits>\n#include <limits>\n#include <type_traits>\n";
                std::set<std::string> included;
                for (const auto& layout : layouts_)
                    if (included.insert(layout.model->position.file).second) cpp += "#include " + quote(layout.model->position.file) + "\n";
                cpp += "\n#if defined(_MSC_VER)\n#define REFLGEN_NATIVE_CDECL __cdecl\n#define REFLGEN_NATIVE_STDCALL __stdcall\n";
                cpp += "#elif defined(__i386__)\n#define REFLGEN_NATIVE_CDECL __attribute__((cdecl))\n#define REFLGEN_NATIVE_STDCALL __attribute__((stdcall))\n";
                cpp += "#else\n#define REFLGEN_NATIVE_CDECL\n#define REFLGEN_NATIVE_STDCALL\n#endif\n";
                cpp += "#if defined(_WIN32)\n#define REFLGEN_NATIVE_EXPORT __declspec(dllexport)\n#else\n#define REFLGEN_NATIVE_EXPORT __attribute__((visibility(\"default\")))\n#endif\n";
                if (!layouts_.empty())
                {
                    const std::string arch = target_.pointer_width == 32 ? "defined(__i386__) || defined(_M_IX86)" :
                        architecture_ == "aarch64" || architecture_ == "arm64" ? "defined(__aarch64__) || defined(_M_ARM64)" :
                        "defined(__x86_64__) || defined(_M_X64)";
                    cpp += "#if !(" + std::string(windows_ ? "defined(_WIN32)" : "defined(__linux__)") + ") || !(" + arch +
                        ") || defined(_M_ARM64EC)\n#error reflgen native table: regenerate for this target\n#endif\n";
                    cpp += "static_assert(CHAR_BIT == 8 && sizeof(void*) * CHAR_BIT == " + std::to_string(target_.pointer_width) +
                        ", \"reflgen native table: target byte/pointer width changed\");\n";
                    cpp += "static_assert(std::numeric_limits<float>::is_iec559 && sizeof(float) == 4 && "
                        "std::numeric_limits<double>::is_iec559 && sizeof(double) == 8, \"reflgen native table requires IEEE binary32/binary64\");\n";
                }
                // Canonical spellings alone do not detect -funsigned-char or a changed target integer width.
                // Prove primitive semantics as well as record layouts against the compiler that builds the host.
                std::map<std::string, const declaration_type*> primitives;
                std::function<void(const declaration_type&)> collect_primitives = [&](const declaration_type& type) {
                    if (type.kind == "signed_integer" || type.kind == "unsigned_integer" || type.kind == "character" ||
                        type.kind == "floating_point") primitives.emplace(type.canonical_spelling, &type);
                    if (type.pointee) collect_primitives(*type.pointee);
                    if (type.element_type) collect_primitives(*type.element_type);
                    if (type.enum_underlying) collect_primitives(*type.enum_underlying);
                    if (type.function_result) collect_primitives(*type.function_result);
                    for (const auto& parameter : type.function_parameters) collect_primitives(parameter);
                };
                for (const auto& layout : layouts_)
                    for (const auto& field : layout.model->table.fields) collect_primitives(field.type);
                for (const auto& [name, value] : completed_)
                {
                    (void)name;
                    collect_primitives(value->underlying);
                    for (const auto& field : value->fields) collect_primitives(field.type);
                }
                for (const auto& [name, primitive] : primitives)
                {
                    const std::string type = "std::remove_cv_t<" + name + ">";
                    cpp += "static_assert(sizeof(" + type + ") == " + std::to_string(primitive->size_bytes) +
                        " && alignof(" + type + ") == " + std::to_string(primitive->align_bytes) +
                        ", \"reflgen native table: primitive layout changed\");\n";
                    if (primitive->kind == "signed_integer" || primitive->kind == "unsigned_integer" ||
                        (primitive->kind == "character" && (name == "char16_t" || name == "char32_t")))
                        cpp += "static_assert(std::numeric_limits<" + type + ">::is_signed == " +
                            (primitive->kind == "signed_integer" ? "true" : "false") +
                            " && std::numeric_limits<" + type + ">::digits == " +
                            std::to_string(primitive->size_bytes * 8 - (primitive->kind == "signed_integer" ? 1 : 0)) +
                            ", \"reflgen native table: integer signedness or representation changed\");\n";
                }
                const auto append_layout = [&](const value_model& value, const std::string& name) {
                    std::string proof = "static_assert(sizeof(" + name + ") == " + std::to_string(value.target.size_bytes) +
                        " && alignof(" + name + ") == " + std::to_string(value.align_bytes) +
                        ", \"reflgen native table: size/alignment changed\");\n";
                    if (value.target.kind == "record")
                    {
                        proof += "static_assert(std::is_standard_layout_v<" + name + "> && std::is_trivially_copyable_v<" + name +
                            "> && !std::is_union_v<" + name + ">, \"reflgen native table requires a standard-layout trivially-copyable non-union\");\n";
                        for (const auto& field : value.fields)
                        {
                            proof += "static_assert(offsetof(" + name + ", " + field.name + ") == " + std::to_string(field.offset_bytes) +
                                ", \"reflgen native table: field offset changed\");\n";
                            proof += "static_assert(std::is_same_v<decltype(" + name + "::" + field.name + "), " + cpp_type(field.type) +
                                ">, \"reflgen native table: field type or calling convention changed\");\n";
                        }
                    }
                    else
                    {
                        proof += "static_assert(std::is_enum_v<" + name + "> && std::is_same_v<std::underlying_type_t<" + name + ">, " +
                            cpp_type(value.underlying) + ">, \"reflgen native table: enum underlying type changed\");\n";
                        for (const auto& item : value.cases)
                            proof += "static_assert(static_cast<" + cpp_type(value.underlying) + ">(" + name + "::" + item.name + ") == " +
                                (value.underlying.kind == "unsigned_integer" ? item.value + "ULL" :
                                 item.value == "-9223372036854775808" ? "(-9223372036854775807LL - 1)" : "(" + item.value + "LL)") +
                                ", \"reflgen native table: enum value changed\");\n";
                    }
                    return proof;
                };
                for (const auto& [name, value] : completed_) cpp += append_layout(*value, "::" + name);
                for (const auto& layout : layouts_)
                {
                    cpp += append_layout(layout.model->table, "::" + layout.model->alias);
                    cpp += "static_assert(" + layout.model->version_expression + " == " + std::to_string(layout.model->version) +
                        ", \"reflgen native table: API version changed; regenerate bindings\");\n";
                }
                cpp += "\n// ABI identity only, not an authenticity or pointer-validity check.\nextern \"C\" REFLGEN_NATIVE_EXPORT std::uint64_t REFLGEN_NATIVE_CDECL reflgen_" +
                    options_.module_name + "_native_abi_fingerprint(void)\n{\n    return 0x" + fingerprint + "ULL;\n}\n";
                return cpp + "#undef REFLGEN_NATIVE_EXPORT\n#undef REFLGEN_NATIVE_STDCALL\n#undef REFLGEN_NATIVE_CDECL\n";
            }

            std::string delegate_parameters(const function_layout& method, bool function_type) const
            {
                if (method.parameters.empty()) return "unit";
                std::string result;
                for (std::size_t i = 0; i < method.parameters.size(); ++i)
                {
                    if (i) result += function_type ? " -> " : " * ";
                    result += method.parameters[i].name;
                }
                return result;
            }

            std::string managed_source(const std::string& fingerprint) const
            {
                std::string fs(banner);
                fs += "// Explicit blittable layouts intentionally use native interop constructs. This warning suppression is file-local.\n#nowarn \"9\"\n";
                fs += "namespace ";
                std::size_t start = 0;
                while (true)
                {
                    const auto end = options_.managed_namespace.find('.', start);
                    if (start) fs += '.';
                    fs += fs_name(options_.managed_namespace.substr(start, end == std::string::npos ? end : end - start));
                    if (end == std::string::npos) break;
                    start = end + 1;
                }
                fs += "\n\nopen System\nopen System.Runtime.InteropServices\n\nmodule reflgen_" + options_.module_name + "_native =\n";
                fs += "    [<Literal>]\n    let AbiFingerprint = 0x" + fingerprint + "UL\n\n";
                fs += "    // Bind only readable borrowed native memory and keep the host code loaded while any binding is used.\n";
                fs += "    // A copied delegate table does not own native objects, stop concurrent mutation, or translate native exceptions.\n";
                for (const auto& layout : layouts_)
                {
                    fs += "    [<Literal>]\n    let " + fs_name(layout.model->managed_name + "Version") + " = " + std::to_string(layout.model->version) + "\n";
                    fs += "    [<Literal>]\n    let " + fs_name(layout.model->managed_name + "Size") + " = " + std::to_string(layout.model->table.target.size_bytes) + "\n";
                }
                fs += '\n';
                for (const auto& [array, index] : ordered_definitions_)
                {
                    if (array)
                    {
                        const auto& a = arrays_[index];
                        fs += "    [<Struct; StructLayout(LayoutKind.Explicit, Size = " + std::to_string(a.size) + ")>]\n    type " + fs_name(a.name) + " =\n";
                        for (long long i = 0; i < a.count; ++i)
                            fs += "        [<FieldOffset(" + std::to_string(i * a.element.size) + ")>]\n        val mutable Item" + std::to_string(i) + ": " + a.element.name + "\n";
                        fs += '\n';
                        continue;
                    }
                    const auto& layout = values_[index];
                    const auto& value = *layout.model;
                    if (value.target.kind == "enum")
                    {
                        fs += "    type " + fs_name(layout.name) + " =";
                        if (value.cases.empty()) fs += " " + layout.fields.front().name + "\n";
                        else
                        {
                            fs += '\n';
                            const std::map<std::string, std::string> suffixes = {
                                {"int8", "y"}, {"uint8", "uy"}, {"int16", "s"}, {"uint16", "us"},
                                {"int32", ""}, {"uint32", "u"}, {"int64", "L"}, {"uint64", "UL"}};
                            for (const auto& item : value.cases)
                                fs += "        | " + fs_name(item.name) + " = " + item.value + suffixes.at(layout.fields.front().name) + "\n";
                        }
                    }
                    else
                    {
                        fs += "    [<Struct; StructLayout(LayoutKind.Explicit, Size = " + std::to_string(value.target.size_bytes) + ")>]\n    type " + fs_name(layout.name) + " =\n";
                        for (std::size_t i = 0; i < value.fields.size(); ++i)
                            fs += "        [<FieldOffset(" + std::to_string(value.fields[i].offset_bytes) + ")>]\n        val mutable " + fs_name(value.fields[i].name) + ": " + layout.fields[i].name + "\n";
                    }
                    fs += '\n';
                }
                for (const auto& table : layouts_)
                    for (const auto& method : table.functions)
                        fs += "    [<UnmanagedFunctionPointer(CallingConvention." + method.calling_convention + ")>]\n    type " + fs_name(method.delegate_name) +
                            " = delegate of " + delegate_parameters(method, false) + " -> " + method.result.name + "\n\n";

                fs += "    // Dispose only after the host has unregistered the callback and finished every in-flight invocation.\n";
                fs += "    // Forgetting Dispose retains the delegate; native code must never call Address after disposal.\n";
                fs += "    type RootedCallback<'T when 'T :> Delegate>(callback: 'T, ?failure: (unit -> exn option)) =\n";
                fs += "        let gate = obj()\n        let callback = if isNull (box callback) then nullArg \"callback\" else callback\n";
                fs += "        let pointer = Marshal.GetFunctionPointerForDelegate(callback)\n        let mutable root = GCHandle.Alloc(callback, GCHandleType.Normal)\n";
                fs += "        let failure = defaultArg failure (fun () -> None)\n";
                fs += "        member _.Address =\n            lock gate (fun () ->\n                if not root.IsAllocated then raise (ObjectDisposedException(\"RootedCallback\"))\n                pointer)\n";
                fs += "        member _.LastException = failure()\n        member _.Dispose() = lock gate (fun () -> if root.IsAllocated then root.Free())\n";
                fs += "        interface IDisposable with member this.Dispose() = this.Dispose()\n\n";

                for (const auto& table : layouts_)
                    for (const auto& method : table.functions)
                    {
                        fs += "    // Managed exceptions are contained and the explicitly supplied fallback crosses the native boundary.\n";
                        fs += "    let " + fs_name("root_" + table.model->managed_name + "_" + method.field->name + "_callback") + " (callback: " +
                            delegate_parameters(method, true) + " -> " + method.result.name + ") (fallback: " + method.result.name + ") =\n";
                        fs += "        let errorGate = obj()\n        let mutable failure: exn option = None\n";
                        fs += "        let thunk = " + fs_name(method.delegate_name) + "(fun ";
                        if (method.parameters.empty()) fs += "()";
                        for (std::size_t i = 0; i < method.parameters.size(); ++i) fs += (i ? " " : "") + std::string("argument_") + std::to_string(i);
                        fs += " ->\n            try callback";
                        if (method.parameters.empty()) fs += " ()";
                        for (std::size_t i = 0; i < method.parameters.size(); ++i) fs += " argument_" + std::to_string(i);
                        fs += "\n            with error ->\n                lock errorGate (fun () -> failure <- Some error)\n                fallback)\n";
                        fs += "        new RootedCallback<" + fs_name(method.delegate_name) + ">(thunk, fun () -> lock errorGate (fun () -> failure))\n\n";
                    }
                fs += "    let private validateTarget () =\n";
                if (layouts_.empty()) fs += "        ()\n\n";
                else
                {
                    const std::string arch = target_.pointer_width == 32 ? "X86" :
                        architecture_ == "arm64" || architecture_ == "aarch64" ? "Arm64" : "X64";
                    fs += "        if IntPtr.Size <> " + std::to_string(target_.pointer_width / 8) + " ||\n";
                    fs += "           RuntimeInformation.ProcessArchitecture <> Architecture." + arch + " ||\n";
                    fs += "           not (RuntimeInformation.IsOSPlatform(OSPlatform." + std::string(windows_ ? "Windows" : "Linux") + ")) then\n";
                    fs += "            invalidOp \"Native table was generated for a different operating system or architecture\"\n\n";
                }
                fs += "    let private validateLayouts () =\n";
                for (const auto& [array, index] : ordered_definitions_)
                {
                    if (array)
                    {
                        const auto& a = arrays_[index];
                        fs += "        if Marshal.SizeOf<" + fs_name(a.name) + ">() <> " + std::to_string(a.size) + " then invalidOp \"Inline array size mismatch\"\n";
                        for (long long i = 0; i < a.count; ++i)
                            fs += "        if Marshal.OffsetOf<" + fs_name(a.name) + ">(" + quote("Item" + std::to_string(i)) + ").ToInt64() <> " +
                                std::to_string(i * a.element.size) + "L then invalidOp \"Inline array offset mismatch\"\n";
                    }
                    else
                    {
                        const auto& layout = values_[index];
                        if (layout.model->target.kind == "enum") continue;
                        fs += "        if Marshal.SizeOf<" + fs_name(layout.name) + ">() <> " + std::to_string(layout.model->target.size_bytes) + " then invalidOp \"Native record size mismatch\"\n";
                        for (const auto& field : layout.model->fields)
                            fs += "        if Marshal.OffsetOf<" + fs_name(layout.name) + ">(" + quote(field.name) + ").ToInt64() <> " +
                                std::to_string(field.offset_bytes) + "L then invalidOp \"Native record field offset mismatch\"\n";
                    }
                }
                fs += "        ()\n\n";
                for (const auto& layout : layouts_)
                {
                    const auto& table = *layout.model;
                    fs += "    type " + fs_name(table.managed_name) + " private (address: nativeint, availableBytes: unativeint) =\n";
                    for (const auto& method : layout.functions)
                        fs += "        let " + fs_name("entry_" + method.field->name) + " = Marshal.GetDelegateForFunctionPointer<" + fs_name(method.delegate_name) +
                            ">(Marshal.ReadIntPtr(address, " + std::to_string(method.field->offset_bytes) + "))\n";
                    fs += "        member _.Address = address\n        member _.AvailableBytes = availableBytes\n";
                    for (const auto& method : layout.functions)
                        fs += "        member _." + fs_name(method.field->name) + " = " + fs_name("entry_" + method.field->name) + "\n";
                    fs += "        static member Bind(address: nativeint, availableBytes: unativeint, fingerprint: uint64) =\n";
                    fs += "            validateTarget()\n            if fingerprint <> AbiFingerprint then invalidArg \"fingerprint\" \"Native table ABI fingerprint mismatch\"\n";
                    fs += "            if address = 0n then invalidArg \"address\" \"Null native table\"\n";
                    fs += "            if availableBytes < 8un then invalidArg \"availableBytes\" \"Native table header is truncated\"\n";
                    fs += "            if uint64 (unativeint address) > uint64 UIntPtr.MaxValue - uint64 availableBytes then invalidArg \"availableBytes\" \"Native table address range overflows\"\n";
                    fs += "            if uint64 (unativeint address) % " + std::to_string(table.table.align_bytes) + "UL <> 0UL then invalidArg \"address\" \"Misaligned native table\"\n";
                    fs += "            if Marshal.ReadInt32(address, " + std::to_string(layout.version_offset) + ") <> " + fs_name(table.managed_name + "Version") +
                        " then invalidArg \"address\" \"Native table API version mismatch\"\n";
                    fs += "            if Marshal.ReadInt32(address, " + std::to_string(layout.size_offset) + ") <> " + fs_name(table.managed_name + "Size") +
                        " then invalidArg \"address\" \"Native table structSize mismatch\"\n";
                    fs += "            if availableBytes < " + std::to_string(table.table.target.size_bytes) + "un then invalidArg \"availableBytes\" \"Native table payload is truncated\"\n";
                    fs += "            validateLayouts()\n";
                    for (const auto& method : layout.functions)
                        fs += "            if Marshal.ReadIntPtr(address, " + std::to_string(method.field->offset_bytes) + ") = 0n then invalidArg \"address\" " +
                            quote("Required native function is null: " + method.field->name) + "\n";
                    fs += "            new " + fs_name(table.managed_name) + "(address, availableBytes)\n\n";
                }
                return fs;
            }

            const target_model& target_;
            const fsharp_table_options& options_;
            diagnostics& report_;
            bool windows_ = false;
            bool linux_ = false;
            std::string architecture_;
            std::map<std::string, const value_model*> models_;
            std::map<std::string, const value_model*> completed_;
            std::set<std::string> visiting_;
            std::set<std::string> pointed_values_;
            std::set<std::string> names_;
            std::vector<array_layout> arrays_;
            std::vector<value_layout> values_;
            std::vector<std::pair<bool, std::size_t>> ordered_definitions_;
            std::vector<table_layout> layouts_;
        };
    }

    fsharp_table_output emit_fsharp_tables(const std::vector<native_table_model>& tables,
                                          const target_model& target, const fsharp_table_options& options,
                                          diagnostics& report)
    {
        return emitter(target, options, report).run(tables);
    }
}
